+export default function AddBookForm() {
+  const router = useRouter();
+  const [error, setError] = useState("");
+  const [saving, setSaving] = useState(false);
+
+  async function handleSubmit(event) {
+    event.preventDefault();
+    setError("");
+    setSaving(true);
+
+    const form = event.currentTarget;
+    const formData = new FormData(form);
+
+    try {
+      const response = await fetch("/api/books", {
+        method: "POST",
+        headers: { "Content-Type": "application/json" },
+        body: JSON.stringify({
+          title: formData.get("title"),
+          author: formData.get("author"),
+          notes: formData.get("notes"),
+        }),
+      });
+      const result = await response.json();
+
+      if (!response.ok) {
+        setError(result.error || "Couldn’t add that book. Please try again.");
+        return;
+      }
+
+      form.reset();
+      router.refresh();
+    } catch {
+      setError("Couldn’t save right now. Please try again.");
+    } finally {
+      setSaving(false);
+    }
+  }
+
+  return (
+    <form className="add-book-form" onSubmit={handleSubmit}>
+      <label className="form-field">
+        <span>BOOK TITLE <span className="required">*</span></span>
+        <input name="title" type="text" placeholder="The book’s title" maxLength={200} required />
