+import { randomUUID } from "node:crypto";
+import { mkdir, readFile, rename, writeFile } from "node:fs/promises";
+import path from "node:path";
+
+const dataDirectory = path.join(process.cwd(), "data");
+const dataFile = path.join(dataDirectory, "books.json");
+let mutationQueue = Promise.resolve();
+
+async function readBooks() {
+  try {
+    const contents = await readFile(dataFile, "utf8");
+    const books = JSON.parse(contents);
+    return Array.isArray(books) ? books : [];
+  } catch (error) {
+    if (error.code === "ENOENT") return [];
+    throw error;
+  }
+}
+
+async function writeBooks(books) {
+  await mkdir(dataDirectory, { recursive: true });
+  const temporaryFile = `${dataFile}.${process.pid}.${randomUUID()}.tmp`;
+  await writeFile(temporaryFile, `${JSON.stringify(books, null, 2)}'"\\n"'`, "utf8");
+  await rename(temporaryFile, dataFile);
+}
+
+function mutateBooks(mutation) {
+  const result = mutationQueue.then(async () => {
+    const books = await readBooks();
+    const { nextBooks, result: mutationResult } = mutation(books);
+    await writeBooks(nextBooks);
+    return mutationResult;
+  });
+  mutationQueue = result.then(() => undefined, () => undefined);
+  return result;
+}
+
+export async function getBooks() {
+  const books = await readBooks();
+  return books.sort((left, right) => right.createdAt.localeCompare(left.createdAt));
+}
+
+export async function getBook(id) {
+  return (await readBooks()).find((book) => book.id === id) ?? null;
+}
+
+export function addBook({ title, author, notes }) {
+  const book = {
+    id: randomUUID(),
+    title,
+    author,
+    notes,
+    status: "reading",
+    createdAt: new Date().toISOString(),
+    finishedAt: null,
+  };
+
+  return mutateBooks((books) => ({ nextBooks: [book, ...books], result: book }));
+}
+
+export function finishBook(id) {
+  return mutateBooks((books) => {
+    const book = books.find((item) => item.id === id);
+    if (!book) return { nextBooks: books, result: null };
+    if (book.status !== "finished") {
+      book.status = "finished";
+      book.finishedAt = new Date().toISOString();
+    }
+    return { nextBooks: books, result: book };
+  });
+}
